style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url("https://i.imgur.com/8RnSP9Z.jpeg") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-position: center !important;
  }

  /* Transparent background so your image shows */
  .container-main, .content, .navbar, .rbx-header, .section-content, .game-page {
    background-color: rgba(255, 255, 255, 0.8) !important;
    border: 5px solid red !important; /* <-- Test border */
  }
}
